'use client'

import { useState } from 'react'
import { LogotipoCriario } from './LogotipoCriario'
import { FaleConosco } from './FaleConosco'
import styles from './CabecalhoSite.module.css'

export function CabecalhoSite() {
  const [menuAberto, setMenuAberto] = useState(false)

  return (
    <header className={styles.cabecalho}>
      <a className={styles.logo} href="#inicio" aria-label="Ir para o início">
        <LogotipoCriario invertido />
      </a>

      <div className={styles.faleConoscoContainer}>
        <FaleConosco />
      </div>

      <button
        className={styles.botaoMenu}
        type="button"
        aria-expanded={menuAberto}
        aria-controls="menu-principal"
        onClick={() => setMenuAberto((aberto) => !aberto)}
      >
        <span className={styles.iconeMenu} aria-hidden="true">
          <i />
          <i />
          <i />
        </span>
        <span>menu</span>
      </button>

      {menuAberto && (
        <div id="menu-principal" className={styles.menuPainel}>
          <a href="#servicos" onClick={() => setMenuAberto(false)}>Serviços</a>
          <a href="#cases" onClick={() => setMenuAberto(false)}>Cases</a>
          <a href="#fale-conosco" onClick={() => setMenuAberto(false)}>Fale conosco</a>
        </div>
      )}
    </header>
  )
}
