'use client'

import { useState } from 'react'
import type { FormEvent } from 'react'

export function FormularioDeContato() {
  const [enviado, setEnviado] = useState(false)

  function lidarComEnvio(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault()
    setEnviado(true)
  }

  return (
    <form className="formulario-contato" onSubmit={lidarComEnvio}>
      <div className="formulario-contato__campos">
        <label>Seu nome<input required name="nome" /></label>
        <label>Empresa<input name="empresa" /></label>
        <label>E-mail<input required type="email" name="email" /></label>
        <label>Telefone<input name="telefone" /></label>
        <label>Cargo<input name="cargo" /></label>
        <label>Como nos conheceu?<input name="origem" /></label>
      </div>
      <label className="formulario-contato__necessidade">Quais são suas necessidades?
        <textarea required name="necessidade" rows={3} />
      </label>
      <button type="submit">{enviado ? 'mensagem preparada' : 'enviar mensagem'} <span aria-hidden="true">↗</span></button>
    </form>
  )
}
